$$\begin{array}{l}
  {m = {\lim\limits_{h\rightarrow 0}\frac{f{({3 + h})} - f{(3)}}{h}}} \\
  {\phantom{m} = {\lim\limits_{h\rightarrow 0}\frac{\frac{3}{3 + h} - 1}{h} = \lim\limits_{h\rightarrow 0}\frac{\frac{3 - {({3 + h})}}{3 + h}}{h}}} \\
  {\phantom{m} = {\lim\limits_{h\rightarrow 0}\frac{- h}{h{({3 + h})}} = \lim\limits_{h\rightarrow 0} - \frac{1}{3 + h} = - \frac{1}{3}}}
  \end{array}$$

$$\begin{array}{l}
  {{\upsilon{(a)}} = {\lim\limits_{h\rightarrow 0}\frac{f{({a + h})} - f{(a)}}{h} = \lim\limits_{h\rightarrow 0}\frac{4.9{({a + h})}^{2} - 4.9a^{2}}{h}}} \\
  {\phantom{\upsilon{(a)}} = {\lim\limits_{h\rightarrow 0}\frac{4.9{({a^{2} + 2ah + h^{2} - a^{2}})}}{h} = \lim\limits_{h\rightarrow 0}\frac{4.9{({2ah + h^{2}})}}{h}}} \\
  {\phantom{\upsilon{(a)}} = {\lim\limits_{h\rightarrow 0}\frac{4.9h{({2a + h})}}{h} = \lim\limits_{h\rightarrow 0}4.9{({2a + h})} = 9.8a}}
  \end{array}$$

$$\begin{array}{l}
  {{f^{\prime}{(a)}} = {\lim\limits_{h\rightarrow 0}\frac{f{({a + h})} - f{(a)}}{h}}} \\
  {\phantom{f^{\prime}{(a)}} = {\lim\limits_{h\rightarrow 0}\frac{{\lbrack{{({a + h})}^{2} - 8{({a + h})} + 9}\rbrack} - {\lbrack{a^{2} - 8a + 9}\rbrack}}{h}}} \\
  {\phantom{f^{\prime}{(a)}} = {\lim\limits_{h\rightarrow 0}\frac{a^{2} + 2ah + h^{2} - 8a - 8h + 9 - a^{2} + 8a - 9}{h}}} \\
  {\phantom{f^{\prime}{(a)}} = {\lim\limits_{h\rightarrow 0}\frac{2ah + h^{2} - 8h}{h} = \lim\limits_{h\rightarrow 0}{({2a + h - 8}) = {2a - 8}}}}
  \end{array}$$
